class BilinearSampler(nn.Module):

    def __init__(self, image_size):
        super(BilinearSampler, self).__init__()
        self.image_size = image_size

    def forward(self, feature_maps, sample_points):
        """
        Args:
            feature_maps (Tensor): The input feature tensor of shape [B, D, H, W].
            sample_points (Tensor): The 2D sample points of shape [B, N_points, 2],
                                    each point in the range [-1, 1], format (x, y).
        Returns:
            Tensor: Sampled feature vectors of shape [B, N_points, D].
        """
        B, D, H, W = feature_maps.shape
        _, N_points, _ = sample_points.shape
        sample_points = sample_points / self.image_size * 2.0 - 1.0
        sample_points = sample_points.unsqueeze(2)
        sampled_features = F.grid_sample(feature_maps, sample_points, mode='bilinear', align_corners=False)
        sampled_features = sampled_features.squeeze(dim=-1).permute(0, 2, 1)
        return sampled_features

class TopoNet(nn.Module):

    def __init__(self, config, feature_dim):
        super(TopoNet, self).__init__()
        self.config = config
        self.hidden_dim = 128
        self.heads = 4
        self.num_attn_layers = 3
        self.feature_proj = nn.Linear(feature_dim, self.hidden_dim)
        self.pair_proj = nn.Linear(2 * self.hidden_dim + 2, self.hidden_dim)
        encoder_layer = nn.TransformerEncoderLayer(d_model=self.hidden_dim, nhead=self.heads, dim_feedforward=self.hidden_dim, dropout=0.1, activation='relu', batch_first=True)
        if self.config.TOPONET_VERSION != 'no_transformer':
            self.transformer_encoder = nn.TransformerEncoder(encoder_layer, num_layers=self.num_attn_layers)
        self.output_proj = nn.Linear(self.hidden_dim, 1)

    def forward(self, points, point_features, pairs, pairs_valid, mask_logits=None):
        point_features = F.relu(self.feature_proj(point_features))
        batch_size, n_samples, n_pairs, _ = pairs.shape
        pairs = pairs.view(batch_size, -1, 2)
        batch_indices = torch.arange(batch_size).view(-1, 1).expand(-1, n_samples * n_pairs)
        src_features = point_features[batch_indices, pairs[:, :, 0]]
        tgt_features = point_features[batch_indices, pairs[:, :, 1]]
        src_points = points[batch_indices, pairs[:, :, 0]]
        tgt_points = points[batch_indices, pairs[:, :, 1]]
        offset = tgt_points - src_points
        if self.config.TOPONET_VERSION == 'no_tgt_features':
            pair_features = torch.concat([src_features, torch.zeros_like(tgt_features), offset], dim=2)
        if self.config.TOPONET_VERSION == 'no_offset':
            pair_features = torch.concat([src_features, tgt_features, torch.zeros_like(offset)], dim=2)
        else:
            pair_features = torch.concat([src_features, tgt_features, offset], dim=2)
        pair_features = F.relu(self.pair_proj(pair_features))
        pair_features = pair_features.view(batch_size * n_samples, n_pairs, -1)
        pairs_valid = pairs_valid.view(batch_size * n_samples, n_pairs)
        all_invalid_pair_mask = torch.eq(torch.sum(pairs_valid, dim=-1), 0).unsqueeze(-1)
        pairs_valid = torch.logical_or(pairs_valid, all_invalid_pair_mask)
        padding_mask = ~pairs_valid
        if self.config.TOPONET_VERSION != 'no_transformer':
            pair_features = self.transformer_encoder(pair_features, src_key_padding_mask=padding_mask)
        _, n_pairs, _ = pair_features.shape
        pair_features = pair_features.view(batch_size, n_samples, n_pairs, -1)
        logits = self.output_proj(pair_features)
        scores = torch.sigmoid(logits)
        return (logits, scores)

def fourier_encode_angle(angle: torch.Tensor, num_bases: int=4) -> torch.Tensor:
    """
    angle: [*, 1] or [*], radians
    return: [*, 2 * num_bases] with [sin(mθ), cos(mθ)]_{m=1..num_bases}
    """
    if angle.dim() == 1:
        angle = angle.unsqueeze(-1)
    outs = []
    for m in range(1, num_bases + 1):
        outs.append(torch.sin(m * angle))
        outs.append(torch.cos(m * angle))
    return torch.cat(outs, dim=-1)

def softmin(t: torch.Tensor, dim: int=-1, tau: float=10.0) -> torch.Tensor:
    return -torch.logsumexp(-tau * t, dim=dim) / tau

def normalize_grid(points_xy: torch.Tensor, image_size: int) -> torch.Tensor:
    """
    points_xy: [B, E, S, 2] in [0, image_size]
    return: normalized to [-1, 1] for grid_sample
    """
    return points_xy / image_size * 2.0 - 1.0

def sample_line_points(src: torch.Tensor, dst: torch.Tensor, num_samples: int) -> torch.Tensor:
    """
    src: [B, E, 2], dst: [B, E, 2]
    return: [B, E, S, 2] where S=num_samples, linear interpolation points
    """
    B, E, _ = src.shape
    t = torch.linspace(0, 1, num_samples, device=src.device).view(1, 1, num_samples, 1)
    src_exp = src.unsqueeze(2)
    dst_exp = dst.unsqueeze(2)
    pts = src_exp + t * (dst_exp - src_exp)
    return pts

class GeodesicPathExtractor(nn.Module):
    """
    Lightweight, differentiable path-aware feature extractor:
    - Sample equidistant points on the line segments from the road probability map in mask_logits
    - Sample multiple times after multi-scale smoothing (avg pooling)
    - Statistical features: mean / std / softmin (softmin of (1-p), approximate worst road)
    Return [B, E, F_path] vector (E is number of edges, S*K)
    """

    def __init__(self, image_size: int, num_samples: int=32, pool_kernel_sizes: Optional[List[int]]=None, tau_softmin: float=10.0):
        super().__init__()
        self.image_size = image_size
        self.num_samples = num_samples
        self.pool_kernel_sizes = pool_kernel_sizes or [1, 5, 11]
        self.tau = tau_softmin

    def forward(self, mask_logits: torch.Tensor, src_points: torch.Tensor, dst_points: torch.Tensor) -> torch.Tensor:
        """
        mask_logits: [B, 2, H, W], road probability in channel 1
        src_points/dst_points: [B, E, 2] in [0, image_size]
        return: [B, E, F_path]
        """
        B, _, H, W = mask_logits.shape
        assert H == self.image_size and W == self.image_size, 'mask size mismatch'
        road_prob = torch.sigmoid(mask_logits[:, 1:2])
        pts = sample_line_points(src_points, dst_points, self.num_samples)
        pts_norm = normalize_grid(pts, self.image_size)
        grid = pts_norm.view(B, -1, 1, 2)
        feats = []
        for ksz in self.pool_kernel_sizes:
            if ksz == 1:
                smoothed = road_prob
            else:
                pad = ksz // 2
                smoothed = F.avg_pool2d(road_prob, kernel_size=ksz, stride=1, padding=pad)
            sampled = F.grid_sample(smoothed, grid, mode='bilinear', align_corners=False)
            sampled = sampled.view(B, -1, self.num_samples)
            mean_v = sampled.mean(dim=-1, keepdim=True)
            std_v = sampled.std(dim=-1, unbiased=False, keepdim=True)
            softmin_v = softmin(1.0 - sampled, dim=-1, tau=self.tau).unsqueeze(-1)
            feats.extend([mean_v, std_v, softmin_v])
        path_feat = torch.cat(feats, dim=-1)
        return path_feat

class BiasedSelfAttentionLayer(nn.Module):
    """
    Customized multi-head self-attention layer with "additive bias" + FFN
    Support batch-wise [B, L, L] shape bias matrix bias
    """

    def __init__(self, d_model: int, nhead: int, dim_ff: int, dropout: float=0.1):
        super().__init__()
        self.d_model = d_model
        self.nhead = nhead
        self.dk = d_model // nhead
        self.q_proj = nn.Linear(d_model, d_model)
        self.k_proj = nn.Linear(d_model, d_model)
        self.v_proj = nn.Linear(d_model, d_model)
        self.out_proj = nn.Linear(d_model, d_model)
        self.dropout = nn.Dropout(dropout)
        self.norm1 = nn.LayerNorm(d_model)
        self.ffn = nn.Sequential(nn.Linear(d_model, dim_ff), nn.ReLU(), nn.Linear(dim_ff, d_model))
        self.norm2 = nn.LayerNorm(d_model)

    def forward(self, x: torch.Tensor, key_padding_mask: Optional[torch.Tensor]=None, bias: Optional[torch.Tensor]=None) -> torch.Tensor:
        """
        x: [B, L, H]
        """
        B, L, H = x.shape
        residual = x
        q = self.q_proj(x).view(B, L, self.nhead, self.dk).transpose(1, 2)
        k = self.k_proj(x).view(B, L, self.nhead, self.dk).transpose(1, 2)
        v = self.v_proj(x).view(B, L, self.nhead, self.dk).transpose(1, 2)
        attn_scores = torch.matmul(q, k.transpose(-2, -1)) / math.sqrt(self.dk)
        if bias is not None:
            attn_scores = attn_scores + bias.unsqueeze(1)
        if key_padding_mask is not None:
            mask = key_padding_mask.unsqueeze(1).unsqueeze(2)
            attn_scores = attn_scores.masked_fill(mask, float('-inf'))
        attn = F.softmax(attn_scores, dim=-1)
        attn = self.dropout(attn)
        out = torch.matmul(attn, v)
        out = out.transpose(1, 2).contiguous().view(B, L, H)
        out = self.out_proj(out)
        x = self.norm1(residual + out)
        residual = x
        x = self.ffn(x)
        x = self.norm2(residual + x)
        return x

def build_edge_bias(src_xy: torch.Tensor, dst_xy: torch.Tensor, valid: torch.Tensor, angle_sigma: float=math.pi / 4, lambda_turn: float=0.6, lambda_compete: float=0.2) -> torch.Tensor:
    """
    Construct edge-edge attention bias matrix within a group of candidate edges at the same source point:
    - turn compatibility: smaller Δθ is more compatible (Gaussian kernel)
    - Competitive prior: negative bias is applied to off-diagonal, encouraging sparse selection
    src_xy/dst_xy: [B, L, 2] (here B is actually B*S, L is N_pairs)
    valid: [B, L], True means valid
    return: bias [B, L, L]
    """
    B, L, _ = src_xy.shape
    offset = dst_xy - src_xy
    angle = torch.atan2(offset[..., 1], offset[..., 0])
    theta_i = angle.unsqueeze(-1)
    theta_j = angle.unsqueeze(-2)
    delta = theta_i - theta_j
    delta = (delta + math.pi) % (2 * math.pi) - math.pi
    k_turn = torch.exp(-delta ** 2 / (2 * angle_sigma ** 2))
    bias_turn = lambda_turn * (k_turn - 0.5)
    eye = torch.eye(L, device=src_xy.device).unsqueeze(0)
    off_diag = 1.0 - eye
    bias_comp = -lambda_compete * off_diag
    bias = bias_turn + bias_comp
    v = valid.float()
    bias = bias * v.unsqueeze(-1) * v.unsqueeze(-2)
    bias = bias * off_diag + 0.0 * eye
    return bias

class MaGTopoNet(nn.Module):
    """
    Mask-aware Geodesic Line-Graph Transformer
    - Optional use of point_features (image features)
    - Use geometric encoding (offset/dist/angle-Fourier)
    - Use path features (multi-scale sampling statistics on the road prob)
    - Do self-attention with biased on the "candidate edge set for each sample"
    Interface kept consistent with TopoNet
    """

    def __init__(self, config, feature_dim: int, use_point_features: bool=True, use_path_features: bool=True, use_edge_bias: bool=True, use_geometric_features: bool=True):
        super().__init__()
        self.config = config
        self.hidden_dim = 256
        self.heads = 8
        self.num_layers = 4
        self.use_point_features = use_point_features
        self.use_path_features = use_path_features
        self.use_edge_bias = use_edge_bias
        self.use_geometric_features = use_geometric_features
        if self.use_point_features:
            self.node_proj = nn.Linear(feature_dim, self.hidden_dim)
        if self.use_geometric_features:
            geo_in_dim = 2 + 1 + 8
            self.geo_proj = nn.Linear(geo_in_dim, self.hidden_dim // 2)
        if self.use_path_features:
            self.path_extractor = GeodesicPathExtractor(image_size=config.PATCH_SIZE, num_samples=config.NUM_INTERPOLATIONS, pool_kernel_sizes=config.POOL_KERNEL_SIZES, tau_softmin=5.0)
            self.path_proj = nn.Linear(9, self.hidden_dim // 2)
        fused_in = 0
        if self.use_point_features:
            fused_in += self.hidden_dim * 2
        if self.use_geometric_features:
            fused_in += self.hidden_dim // 2
        if self.use_path_features:
            fused_in += self.hidden_dim // 2
        if fused_in == 0:
            raise ValueError('At least one feature type must be enabled: use_point_features, use_geometric_features, or use_path_features. Note: use_edge_bias is independent and provides attention bias, not features.')
        self.edge_proj = nn.Linear(fused_in, self.hidden_dim)
        self.layers = nn.ModuleList([BiasedSelfAttentionLayer(self.hidden_dim, self.heads, dim_ff=self.hidden_dim, dropout=0.1) for _ in range(self.num_layers)])
        self.out = nn.Linear(self.hidden_dim, 1)

    def forward(self, points: torch.Tensor, point_features: torch.Tensor, pairs: torch.Tensor, pairs_valid: torch.Tensor, mask_logits: Optional[torch.Tensor]=None):
        B, S, K, _ = pairs.shape
        dev = points.device
        pairs_flat = pairs.view(B, -1, 2)
        BE = S * K
        batch_idx = torch.arange(B, device=dev).view(-1, 1).expand(-1, BE)
        src_xy = points[batch_idx, pairs_flat[:, :, 0]].float()
        dst_xy = points[batch_idx, pairs_flat[:, :, 1]].float()
        if self.use_point_features:
            node = F.gelu(self.node_proj(point_features))
            src_idx = pairs_flat[:, :, 0]
            dst_idx = pairs_flat[:, :, 1]
            src_feat = node[batch_idx, src_idx]
            dst_feat = node[batch_idx, dst_idx]
        if self.use_geometric_features:
            offset = dst_xy - src_xy
            dist = torch.norm(offset, dim=-1, keepdim=True)
            angle = torch.atan2(offset[..., 1], offset[..., 0]).unsqueeze(-1)
            angle_enc = fourier_encode_angle(angle, num_bases=4)
            offset_norm = offset / mask_logits.shape[-1]
            dist_norm = dist / (math.sqrt(2) * mask_logits.shape[-1])
            geo_in = torch.cat([offset_norm, dist_norm, angle_enc], dim=-1)
            geo_feat = F.gelu(self.geo_proj(geo_in))
        if self.use_path_features:
            assert mask_logits is not None, 'mask_logits is required when use_path_features=True'
            path_feat_raw = self.path_extractor(mask_logits, src_xy, dst_xy)
            path_feat = F.gelu(self.path_proj(path_feat_raw))
        feats = []
        if self.use_point_features:
            feats.extend([src_feat, dst_feat])
        if self.use_geometric_features:
            feats.append(geo_feat)
        if self.use_path_features:
            feats.append(path_feat)
        edge_tok = torch.cat(feats, dim=-1)
        edge_tok = F.gelu(self.edge_proj(edge_tok))
        x = edge_tok.view(B, S, K, -1).view(B * S, K, -1)
        valid = pairs_valid.view(B * S, K)
        all_invalid = valid.sum(dim=-1, keepdim=True) == 0
        valid = torch.logical_or(valid, all_invalid)
        if self.use_edge_bias:
            src_xy_g = src_xy.view(B, S, K, 2).view(B * S, K, 2)
            dst_xy_g = dst_xy.view(B, S, K, 2).view(B * S, K, 2)
            bias = build_edge_bias(src_xy_g, dst_xy_g, valid, angle_sigma=self.config.ANGLE_SIGMA, lambda_turn=self.config.LAMBDA_TURN, lambda_compete=self.config.LAMBDA_COMPETE)
        else:
            bias = None
        key_padding_mask = ~valid
        for layer in self.layers:
            x = layer(x, key_padding_mask=key_padding_mask, bias=bias)
        x = x.view(B, S, K, -1)
        logits = self.out(x)
        scores = torch.sigmoid(logits)
        return (logits, scores)

class _LoRA_qkv(nn.Module):
    """In Sam it is implemented as
    self.qkv = nn.Linear(dim, dim * 3, bias=qkv_bias)
    B, N, C = x.shape
    qkv = self.qkv(x).reshape(B, N, 3, self.num_heads, self.head_dim).permute(2, 0, 3, 1, 4)
    q, k, v = qkv.unbind(0)
    """

    def __init__(self, qkv: nn.Module, linear_a_q: nn.Module, linear_b_q: nn.Module, linear_a_v: nn.Module, linear_b_v: nn.Module):
        super().__init__()
        self.weight = qkv.weight
        self.bias = qkv.bias
        self.linear_a_q = linear_a_q
        self.linear_b_q = linear_b_q
        self.linear_a_v = linear_a_v
        self.linear_b_v = linear_b_v
        self.dim = qkv.in_features
        self.w_identity = torch.eye(qkv.in_features)

    def forward(self, x):
        qkv = F.linear(x, self.weight, self.bias)
        new_q = self.linear_b_q(self.linear_a_q(x))
        new_v = self.linear_b_v(self.linear_a_v(x))
        qkv[:, :, :, :self.dim] += new_q
        qkv[:, :, :, -self.dim:] += new_v
        return qkv

class MaGRoad(nn.Module):

    def __init__(self, config):
        super().__init__()
        self.config = config
        assert config.SAM_VERSION in {'vit_b', 'vit_l', 'vit_h'}
        if config.SAM_VERSION == 'vit_b':
            encoder_embed_dim = 768
            encoder_depth = 12
            encoder_num_heads = 12
            encoder_global_attn_indexes = [2, 5, 8, 11]
        elif config.SAM_VERSION == 'vit_l':
            encoder_embed_dim = 1024
            encoder_depth = 24
            encoder_num_heads = 16
            encoder_global_attn_indexes = [5, 11, 17, 23]
        elif config.SAM_VERSION == 'vit_h':
            encoder_embed_dim = 1280
            encoder_depth = 32
            encoder_num_heads = 16
            encoder_global_attn_indexes = [7, 15, 23, 31]
        prompt_embed_dim = 256
        image_size = config.PATCH_SIZE
        self.image_size = image_size
        vit_patch_size = 16
        image_embedding_size = image_size // vit_patch_size
        encoder_output_dim = prompt_embed_dim
        self.register_buffer('pixel_mean', torch.Tensor([123.675, 116.28, 103.53]).view(-1, 1, 1), False)
        self.register_buffer('pixel_std', torch.Tensor([58.395, 57.12, 57.375]).view(-1, 1, 1), False)
        if self.config.NO_SAM:
            self.image_encoder = vitdet.VITBEncoder(image_size=image_size, output_feature_dim=prompt_embed_dim)
            self.matched_param_names = self.image_encoder.matched_param_names
        else:
            self.image_encoder = ImageEncoderViT(depth=encoder_depth, embed_dim=encoder_embed_dim, img_size=image_size, mlp_ratio=4, norm_layer=partial(torch.nn.LayerNorm, eps=1e-06), num_heads=encoder_num_heads, patch_size=vit_patch_size, qkv_bias=True, use_rel_pos=True, global_attn_indexes=encoder_global_attn_indexes, window_size=14, out_chans=prompt_embed_dim)
        if self.config.USE_SAM_DECODER:
            self.prompt_encoder = PromptEncoder(embed_dim=prompt_embed_dim, image_embedding_size=(image_embedding_size, image_embedding_size), input_image_size=(image_size, image_size), mask_in_chans=16)
            for param in self.prompt_encoder.parameters():
                param.requires_grad = False
            self.mask_decoder = MaskDecoder(num_multimask_outputs=2, transformer=TwoWayTransformer(depth=2, embedding_dim=prompt_embed_dim, mlp_dim=2048, num_heads=8), transformer_dim=prompt_embed_dim, iou_head_depth=3, iou_head_hidden_dim=256)
        else:
            activation = nn.GELU
            self.map_decoder = nn.Sequential(nn.ConvTranspose2d(encoder_output_dim, 128, kernel_size=2, stride=2), LayerNorm2d(128), activation(), nn.ConvTranspose2d(128, 64, kernel_size=2, stride=2), activation(), nn.ConvTranspose2d(64, 32, kernel_size=2, stride=2), activation(), nn.ConvTranspose2d(32, 2, kernel_size=2, stride=2))
        self.bilinear_sampler = BilinearSampler(image_size=self.image_size)
        if config.TOPONET == 'transformer':
            self.topo_net = TopoNet(config, encoder_output_dim)
        elif config.TOPONET == 'maGTopoNet':
            self.topo_net = MaGTopoNet(config, encoder_output_dim, use_point_features=config.USE_POINT_FEATURES, use_path_features=config.USE_PATH_FEATURES, use_edge_bias=config.USE_EDGE_BIAS, use_geometric_features=config.USE_GEOMETRIC_FEATURES)
        if config.ENCODER_LORA:
            r = self.config.LORA_RANK
            lora_layer_selection = None
            assert r > 0
            if lora_layer_selection:
                self.lora_layer_selection = lora_layer_selection
            else:
                self.lora_layer_selection = list(range(len(self.image_encoder.blocks)))
            self.w_As = []
            self.w_Bs = []
            for param in self.image_encoder.parameters():
                param.requires_grad = False
            for t_layer_i, blk in enumerate(self.image_encoder.blocks):
                if t_layer_i not in self.lora_layer_selection:
                    continue
                w_qkv_linear = blk.attn.qkv
                dim = w_qkv_linear.in_features
                w_a_linear_q = nn.Linear(dim, r, bias=False)
                w_b_linear_q = nn.Linear(r, dim, bias=False)
                w_a_linear_v = nn.Linear(dim, r, bias=False)
                w_b_linear_v = nn.Linear(r, dim, bias=False)
                self.w_As.append(w_a_linear_q)
                self.w_Bs.append(w_b_linear_q)
                self.w_As.append(w_a_linear_v)
                self.w_Bs.append(w_b_linear_v)
                blk.attn.qkv = _LoRA_qkv(w_qkv_linear, w_a_linear_q, w_b_linear_q, w_a_linear_v, w_b_linear_v)
            for w_A in self.w_As:
                nn.init.kaiming_uniform_(w_A.weight, a=math.sqrt(5))
            for w_B in self.w_Bs:
                nn.init.zeros_(w_B.weight)

    def forward(self, rgb, graph_points, pairs, valid):
        x = rgb.permute(0, 3, 1, 2)
        x = (x - self.pixel_mean) / self.pixel_std
        image_embeddings = self.image_encoder(x)
        if self.config.USE_SAM_DECODER:
            sparse_embeddings, dense_embeddings = self.prompt_encoder(points=None, boxes=None, masks=None)
            low_res_logits, iou_predictions = self.mask_decoder(image_embeddings=image_embeddings, image_pe=self.prompt_encoder.get_dense_pe(), sparse_prompt_embeddings=sparse_embeddings, dense_prompt_embeddings=dense_embeddings, multimask_output=True)
            mask_logits = F.interpolate(low_res_logits, (self.image_encoder.img_size, self.image_encoder.img_size), mode='bilinear', align_corners=False)
            mask_scores = torch.sigmoid(mask_logits)
        else:
            mask_logits = self.map_decoder(image_embeddings)
            mask_scores = torch.sigmoid(mask_logits)
        point_features = self.bilinear_sampler(image_embeddings, graph_points)
        topo_logits, topo_scores = self.topo_net(graph_points, point_features, pairs, valid, mask_logits)
        mask_logits = mask_logits.permute(0, 2, 3, 1)
        mask_scores = mask_scores.permute(0, 2, 3, 1)
        return (mask_logits, mask_scores, topo_logits, topo_scores)

    def infer_masks_and_img_features(self, rgb):
        x = rgb.permute(0, 3, 1, 2)
        x = (x - self.pixel_mean) / self.pixel_std
        image_embeddings = self.image_encoder(x)
        if self.config.USE_SAM_DECODER:
            sparse_embeddings, dense_embeddings = self.prompt_encoder(points=None, boxes=None, masks=None)
            low_res_logits, iou_predictions = self.mask_decoder(image_embeddings=image_embeddings, image_pe=self.prompt_encoder.get_dense_pe(), sparse_prompt_embeddings=sparse_embeddings, dense_prompt_embeddings=dense_embeddings, multimask_output=True)
            mask_logits = F.interpolate(low_res_logits, (self.image_encoder.img_size, self.image_encoder.img_size), mode='bilinear', align_corners=False)
            mask_scores = torch.sigmoid(mask_logits)
        else:
            mask_logits = self.map_decoder(image_embeddings)
            mask_scores = torch.sigmoid(mask_logits)
        mask_scores = mask_scores.permute(0, 2, 3, 1)
        return (image_embeddings, mask_logits, mask_scores)

    def infer_toponet(self, image_embeddings, graph_points, pairs, valid, mask_logits):
        point_features = self.bilinear_sampler(image_embeddings, graph_points)
        topo_logits, topo_scores = self.topo_net(graph_points, point_features, pairs, valid, mask_logits)
        return topo_scores
